    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def backtrack(current, path):
        if current.row == goal[0] and current.col == goal[1]:
            return path + [current]
        current.visited = True
        for dr, dc in directions:
            nr, nc = current.row + dr, current.col + dc
            if is_valid(nr, nc) and not grid[nr][nc].visited:
                new_cell = Cell(nr, nc)
                if backtrack(new_cell, path + [current]):
                    return backtrack(new_cell, path + [current])
        return []

    start_cell = Cell(start[0], start[1])
    result = backtrack(start_cell, [])
    if result:
        return result
    return []

