#include <vector>
#include <queue>
#include <climits>
using namespace std;

class Solution {
public:
    int solve(int n, vector<vector<int>>& edges, int s, int t) {
        // If start and target are the same, return 0
        if (s == t) return 0;

        // Initialize distance array with infinity
        vector<int> dist(n, INT_MAX);
        dist[s] = 0;

        // Use a priority queue for Dijkstra's algorithm
        priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;
        pq.push({0, s});

        // Build adjacency list
        vector<vector<pair<int, int>>> adj(n);
        for (auto& e : edges) {
            adj[e[0]].push_back({e[1], e[2]});
        }

        while (!pq.empty()) {
            int current_dist = pq.top().first;
            int u = pq.top().second;
            pq.pop();

            // If we've already found a shorter path to u, skip
            if (current_dist > dist[u]) continue;

            for (auto& neighbor : adj[u]) {
                int v = neighbor.first;
                int weight = neighbor.second;
                int new_dist = dist[u] + weight;

                // If a shorter path is found, update and push to queue
                if (new_dist < dist[v]) {
                    dist[v] = new_dist;
                    pq.push({new_dist, v});
                }
            }
        }

        // If distance is still infinity, no path exists
        return dist[t] != INT_MAX ? dist[t] : -1;
    }
};

