def solve(n, edges):
    from collections import defaultdict

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * n
    count = 0

    for node in range(n):
        if not visited[node]:
            count += 1
            stack = [node]
            visited[node] = True
            while stack:
